import{_ as t,o as i,c as e,a1 as a}from"./chunks/framework.DdbKPUhY.js";const g=JSON.parse('{"title":"CI/CD 工作流文档","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/CI_CD.md","filePath":"zh/dev/CI_CD.md"}'),r={name:"zh/dev/CI_CD.md"};function o(s,l,n,u,d,c){return i(),e("div",null,[...l[0]||(l[0]=[a('<h1 id="ci-cd-工作流文档" tabindex="-1">CI/CD 工作流文档 <a class="header-anchor" href="#ci-cd-工作流文档" aria-label="Permalink to &quot;CI/CD 工作流文档&quot;">​</a></h1><p>本文档详细说明了 UVHTTP 项目的 CI/CD 工作流配置和用途。</p><h2 id="工作流概览" tabindex="-1">工作流概览 <a class="header-anchor" href="#工作流概览" aria-label="Permalink to &quot;工作流概览&quot;">​</a></h2><p>UVHTTP 使用 GitHub Actions 实现自动化 CI/CD，专注于 Linux 平台，包含以下工作流：</p><table tabindex="0"><thead><tr><th>工作流名称</th><th>触发条件</th><th>目的</th><th>运行时间</th></tr></thead><tbody><tr><td>CI/CD - PR Quick Validation</td><td>PR 到 main/develop</td><td>快速验证 PR</td><td>~15分钟</td></tr><tr><td>CI/CD - Push Full Validation</td><td>Push 到 main/develop/feature/*</td><td>完整验证代码变更</td><td>~35分钟</td></tr><tr><td>CI/CD - Nightly Deep Test</td><td>每日定时</td><td>深度测试代码质量</td><td>~100分钟</td></tr><tr><td>CI/CD - Release Build</td><td>Push tag v*</td><td>构建和发布正式版本</td><td>~60分钟</td></tr><tr><td>CI/CD - Deploy Documentation</td><td>Push 到 main/release/* + docs/**</td><td>部署文档到 GitHub Pages</td><td>~15分钟</td></tr><tr><td>CI/CD - Notification Service</td><td>其他 workflow 完成</td><td>发送 CI/CD 结果通知</td><td>~5分钟</td></tr><tr><td>Security Issue Creator</td><td>安全扫描完成</td><td>自动创建安全 Issue</td><td>~10分钟</td></tr></tbody></table><h2 id="工作流详细说明" tabindex="-1">工作流详细说明 <a class="header-anchor" href="#工作流详细说明" aria-label="Permalink to &quot;工作流详细说明&quot;">​</a></h2><h3 id="_1-ci-cd-pr-quick-validation" tabindex="-1">1. CI/CD - PR Quick Validation <a class="header-anchor" href="#_1-ci-cd-pr-quick-validation" aria-label="Permalink to &quot;1. CI/CD - PR Quick Validation&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/workflows/ci-pr.yml</code></p><p><strong>触发条件</strong>:</p><ul><li>Pull Request 打开、同步、重新打开到 <code>main</code> 或 <code>develop</code> 分支</li></ul><p><strong>包含的 Job</strong>:</p><h4 id="ubuntu-build" tabindex="-1">ubuntu-build <a class="header-anchor" href="#ubuntu-build" aria-label="Permalink to &quot;ubuntu-build&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 20分钟</li><li><strong>功能</strong>: <ul><li>检出代码（包含子模块）</li><li>配置 CMake（Release 模式，启用示例）</li><li>编译项目</li><li>检查编译警告（零警告原则）</li><li>上传构建产物（保留7天）</li></ul></li></ul><h4 id="code-quality-check" tabindex="-1">code-quality-check <a class="header-anchor" href="#code-quality-check" aria-label="Permalink to &quot;code-quality-check&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 10分钟</li><li><strong>功能</strong>: <ul><li>安装 cppcheck 和 clang-tidy</li><li>运行静态代码分析</li><li>上传分析结果（保留7天）</li></ul></li></ul><h4 id="dependency-scan" tabindex="-1">dependency-scan <a class="header-anchor" href="#dependency-scan" aria-label="Permalink to &quot;dependency-scan&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 5分钟</li><li><strong>功能</strong>: <ul><li>检查 .gitmodules 中的依赖</li><li>扫描依赖漏洞</li></ul></li></ul><h4 id="ubuntu-test-fast" tabindex="-1">ubuntu-test-fast <a class="header-anchor" href="#ubuntu-test-fast" aria-label="Permalink to &quot;ubuntu-test-fast&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 10分钟</li><li><strong>依赖</strong>: ubuntu-build</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>使用 <code>run-tests</code> action 运行快速测试</li><li>上传测试日志（保留7天）</li></ul></li></ul><h4 id="performance-regression-check" tabindex="-1">performance-regression-check <a class="header-anchor" href="#performance-regression-check" aria-label="Permalink to &quot;performance-regression-check&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 15分钟</li><li><strong>依赖</strong>: ubuntu-build</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>安装 wrk</li><li>运行快速性能测试（3个场景，每个5秒）</li><li>与基线对比性能指标</li><li>检测性能回归</li><li>上传性能结果（保留7天）</li></ul></li></ul><h4 id="generate-pr-summary" tabindex="-1">generate-pr-summary <a class="header-anchor" href="#generate-pr-summary" aria-label="Permalink to &quot;generate-pr-summary&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 2分钟</li><li><strong>依赖</strong>: 所有其他任务</li><li><strong>功能</strong>: <ul><li>生成 PR 摘要</li><li>在 PR 中添加评论</li></ul></li></ul><p><strong>并发控制</strong>: 取消同一 PR 的旧运行</p><hr><h3 id="_2-ci-cd-push-full-validation" tabindex="-1">2. CI/CD - Push Full Validation <a class="header-anchor" href="#_2-ci-cd-push-full-validation" aria-label="Permalink to &quot;2. CI/CD - Push Full Validation&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/workflows/ci-push.yml</code></p><p><strong>触发条件</strong>:</p><ul><li>Push 到 <code>main</code>, <code>develop</code>, <code>feature/*</code> 分支</li><li>手动触发</li></ul><p><strong>包含的 Job</strong>:</p><h4 id="ubuntu-build-1" tabindex="-1">ubuntu-build <a class="header-anchor" href="#ubuntu-build-1" aria-label="Permalink to &quot;ubuntu-build&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 20分钟</li><li><strong>功能</strong>: <ul><li>检出代码（包含子模块）</li><li>配置 CMake（Release 模式，启用 WebSocket 和 mimalloc）</li><li>编译项目</li><li>上传构建产物（保留7天）</li></ul></li></ul><h4 id="code-quality-check-1" tabindex="-1">code-quality-check <a class="header-anchor" href="#code-quality-check-1" aria-label="Permalink to &quot;code-quality-check&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 15分钟</li><li><strong>功能</strong>: <ul><li>安装 cppcheck</li><li>运行静态代码分析</li><li>上传分析结果（保留7天）</li></ul></li></ul><h4 id="security-scan" tabindex="-1">security-scan <a class="header-anchor" href="#security-scan" aria-label="Permalink to &quot;security-scan&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 20分钟</li><li><strong>功能</strong>: <ul><li>运行 CodeQL 安全分析</li><li>上传分析结果</li></ul></li></ul><h4 id="ubuntu-test-full" tabindex="-1">ubuntu-test-full <a class="header-anchor" href="#ubuntu-test-full" aria-label="Permalink to &quot;ubuntu-test-full&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 20分钟</li><li><strong>依赖</strong>: ubuntu-build</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>设置可执行权限</li><li>使用 <code>run-tests</code> action 运行完整测试</li><li>上传测试日志（保留7天）</li></ul></li></ul><h4 id="performance-benchmark" tabindex="-1">performance-benchmark <a class="header-anchor" href="#performance-benchmark" aria-label="Permalink to &quot;performance-benchmark&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 35分钟</li><li><strong>依赖</strong>: ubuntu-test-full</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>安装 wrk</li><li>运行性能测试（8个场景）</li><li>解析性能结果</li><li>生成性能报告</li><li>更新性能基线历史</li><li>上传性能结果（保留30天）</li></ul></li></ul><h4 id="generate-summary" tabindex="-1">generate-summary <a class="header-anchor" href="#generate-summary" aria-label="Permalink to &quot;generate-summary&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 5分钟</li><li><strong>依赖</strong>: ubuntu-test-full, performance-benchmark</li><li><strong>功能</strong>: <ul><li>生成 CI/CD 摘要</li><li>更新 GitHub Step Summary</li></ul></li></ul><p><strong>并发控制</strong>: 取消同一分支的旧运行</p><hr><h3 id="_3-ci-cd-nightly-deep-test" tabindex="-1">3. CI/CD - Nightly Deep Test <a class="header-anchor" href="#_3-ci-cd-nightly-deep-test" aria-label="Permalink to &quot;3. CI/CD - Nightly Deep Test&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/workflows/ci-nightly.yml</code></p><p><strong>触发条件</strong>:</p><ul><li>每日 UTC 0:00 定时运行</li><li>手动触发</li></ul><p><strong>包含的 Job</strong>:</p><h4 id="ubuntu-build-all" tabindex="-1">ubuntu-build-all <a class="header-anchor" href="#ubuntu-build-all" aria-label="Permalink to &quot;ubuntu-build-all&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 25分钟</li><li><strong>功能</strong>: <ul><li>检出代码（包含子模块）</li><li>配置 CMake（Debug 模式，启用覆盖率）</li><li>编译项目</li><li>上传构建产物（保留7天）</li></ul></li></ul><h4 id="code-quality-full" tabindex="-1">code-quality-full <a class="header-anchor" href="#code-quality-full" aria-label="Permalink to &quot;code-quality-full&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 15分钟</li><li><strong>功能</strong>: <ul><li>运行 cppcheck</li><li>运行 clang-tidy</li><li>运行 clang-format</li><li>上传分析结果（保留30天）</li></ul></li></ul><h4 id="security-scan-full" tabindex="-1">security-scan-full <a class="header-anchor" href="#security-scan-full" aria-label="Permalink to &quot;security-scan-full&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 20分钟</li><li><strong>功能</strong>: <ul><li>运行 CodeQL 安全分析</li><li>运行 cppcheck 安全检查</li><li>上传分析结果（保留30天）</li></ul></li></ul><h4 id="test-coverage" tabindex="-1">test-coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;test-coverage&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 20分钟</li><li><strong>依赖</strong>: ubuntu-build-all</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>使用 <code>run-tests</code> action 运行覆盖率测试</li><li>生成覆盖率报告</li><li>上传覆盖率报告（保留30天）</li><li>上传到 Codecov</li></ul></li></ul><h4 id="test-memory" tabindex="-1">test-memory <a class="header-anchor" href="#test-memory" aria-label="Permalink to &quot;test-memory&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 20分钟</li><li><strong>依赖</strong>: ubuntu-build-all</li><li><strong>功能</strong>: <ul><li>配置 CMake（启用 AddressSanitizer）</li><li>编译项目</li><li>使用 <code>run-tests</code> action 运行内存测试</li><li>上传内存测试结果（保留30天）</li></ul></li></ul><h4 id="test-stress" tabindex="-1">test-stress <a class="header-anchor" href="#test-stress" aria-label="Permalink to &quot;test-stress&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 35分钟</li><li><strong>依赖</strong>: ubuntu-build-all</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>运行压力测试</li><li>上传压力测试结果（保留30天）</li></ul></li></ul><h4 id="performance-full" tabindex="-1">performance-full <a class="header-anchor" href="#performance-full" aria-label="Permalink to &quot;performance-full&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 35分钟</li><li><strong>依赖</strong>: ubuntu-build-all</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>运行完整性能测试（8个场景）</li><li>上传性能结果（保留30天）</li></ul></li></ul><h4 id="generate-nightly-report" tabindex="-1">generate-nightly-report <a class="header-anchor" href="#generate-nightly-report" aria-label="Permalink to &quot;generate-nightly-report&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 10分钟</li><li><strong>依赖</strong>: 所有测试任务</li><li><strong>功能</strong>: <ul><li>生成每日测试报告</li><li>更新 GitHub Step Summary</li></ul></li></ul><hr><h3 id="_4-ci-cd-release-build" tabindex="-1">4. CI/CD - Release Build <a class="header-anchor" href="#_4-ci-cd-release-build" aria-label="Permalink to &quot;4. CI/CD - Release Build&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/workflows/ci-release.yml</code></p><p><strong>触发条件</strong>:</p><ul><li>Push tag matching <code>v*</code>（如 v1.5.0）</li><li>手动触发</li></ul><p><strong>包含的 Job</strong>:</p><h4 id="ubuntu-release-build" tabindex="-1">ubuntu-release-build <a class="header-anchor" href="#ubuntu-release-build" aria-label="Permalink to &quot;ubuntu-release-build&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 25分钟</li><li><strong>功能</strong>: <ul><li>检出代码（包含子模块）</li><li>获取版本号</li><li>配置 CMake（Release 模式，启用 WebSocket 和 mimalloc）</li><li>编译项目</li><li>上传构建产物（保留30天）</li></ul></li></ul><h4 id="release-test" tabindex="-1">release-test <a class="header-anchor" href="#release-test" aria-label="Permalink to &quot;release-test&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 25分钟</li><li><strong>依赖</strong>: ubuntu-release-build</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>运行发布测试</li><li>上传测试日志（保留30天）</li></ul></li></ul><h4 id="create-release" tabindex="-1">create-release <a class="header-anchor" href="#create-release" aria-label="Permalink to &quot;create-release&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 10分钟</li><li><strong>依赖</strong>: release-test</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>生成 Release Notes</li><li>创建 GitHub Release</li></ul></li></ul><h4 id="update-baseline" tabindex="-1">update-baseline <a class="header-anchor" href="#update-baseline" aria-label="Permalink to &quot;update-baseline&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 10分钟</li><li><strong>依赖</strong>: create-release</li><li><strong>功能</strong>: <ul><li>下载构建产物</li><li>运行性能基准测试</li><li>更新性能基线</li><li>创建 PR 更新基线</li></ul></li></ul><hr><h3 id="_5-ci-cd-deploy-documentation" tabindex="-1">5. CI/CD - Deploy Documentation <a class="header-anchor" href="#_5-ci-cd-deploy-documentation" aria-label="Permalink to &quot;5. CI/CD - Deploy Documentation&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/workflows/deploy-docs.yml</code></p><p><strong>触发条件</strong>:</p><ul><li>Push 到 <code>main</code> 或 <code>release/*</code> 分支</li><li><code>docs/**</code> 路径有变化</li><li>手动触发</li></ul><p><strong>包含的 Job</strong>:</p><h4 id="build-and-deploy" tabindex="-1">build-and-deploy <a class="header-anchor" href="#build-and-deploy" aria-label="Permalink to &quot;build-and-deploy&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 15分钟</li><li><strong>功能</strong>: <ul><li>检出代码（包含子模块）</li><li>设置 Node.js 环境</li><li>设置 pnpm</li><li>安装依赖</li><li>构建 VitePress 文档</li><li>部署到 GitHub Pages</li></ul></li></ul><hr><h3 id="_6-ci-cd-notification-service" tabindex="-1">6. CI/CD - Notification Service <a class="header-anchor" href="#_6-ci-cd-notification-service" aria-label="Permalink to &quot;6. CI/CD - Notification Service&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/workflows/notify.yml</code></p><p><strong>触发条件</strong>:</p><ul><li>监听其他 workflow 完成</li></ul><p><strong>包含的 Job</strong>:</p><h4 id="notify" tabindex="-1">notify <a class="header-anchor" href="#notify" aria-label="Permalink to &quot;notify&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 5分钟</li><li><strong>功能</strong>: <ul><li>下载 workflow 产物</li><li>解析 workflow 结果</li><li>发送通知（PR 评论、Issue 创建）</li></ul></li></ul><hr><h3 id="_7-security-issue-creator" tabindex="-1">7. Security Issue Creator <a class="header-anchor" href="#_7-security-issue-creator" aria-label="Permalink to &quot;7. Security Issue Creator&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/workflows/security-issue-creator.yml</code></p><p><strong>触发条件</strong>:</p><ul><li>监听安全扫描 workflow 完成</li></ul><p><strong>包含的 Job</strong>:</p><h4 id="create-security-issue" tabindex="-1">create-security-issue <a class="header-anchor" href="#create-security-issue" aria-label="Permalink to &quot;create-security-issue&quot;">​</a></h4><ul><li><strong>平台</strong>: Ubuntu Latest</li><li><strong>超时</strong>: 10分钟</li><li><strong>功能</strong>: <ul><li>下载安全扫描结果</li><li>检测安全问题</li><li>创建安全 Issue</li><li>更新 Issue 状态</li></ul></li></ul><hr><h2 id="可重用-actions" tabindex="-1">可重用 Actions <a class="header-anchor" href="#可重用-actions" aria-label="Permalink to &quot;可重用 Actions&quot;">​</a></h2><h3 id="setup-build" tabindex="-1">setup-build <a class="header-anchor" href="#setup-build" aria-label="Permalink to &quot;setup-build&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/actions/setup-build/action.yml</code></p><p><strong>功能</strong>: 设置构建环境和安装依赖</p><p><strong>输入</strong>:</p><ul><li><code>os</code>: 操作系统（ubuntu-latest）</li></ul><p><strong>输出</strong>: 无</p><hr><h3 id="cache-deps" tabindex="-1">cache-deps <a class="header-anchor" href="#cache-deps" aria-label="Permalink to &quot;cache-deps&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/actions/cache-deps/action.yml</code></p><p><strong>功能</strong>: 缓存 CMake 依赖</p><p><strong>输入</strong>:</p><ul><li><code>cache-key</code>: 缓存键（用于标识）</li><li><code>build-type</code>: 构建类型（Release、Debug）</li></ul><p><strong>缓存键格式</strong>: <code>deps-{RUNNER_OS}-{BUILD_TYPE}-{HASH}</code></p><hr><h3 id="run-tests" tabindex="-1">run-tests <a class="header-anchor" href="#run-tests" aria-label="Permalink to &quot;run-tests&quot;">​</a></h3><p><strong>文件</strong>: <code>.github/actions/run-tests/action.yml</code></p><p><strong>功能</strong>: 运行测试并收集结果</p><p><strong>输入</strong>:</p><ul><li><code>build-dir</code>: 构建目录</li><li><code>test-type</code>: 测试类型（fast、slow、all、coverage、stress、memory）</li><li><code>timeout</code>: 测试超时时间（秒）</li><li><code>parallel</code>: 并行测试数量</li></ul><p><strong>输出</strong>:</p><ul><li><code>status</code>: 测试状态（success、failed）</li><li><code>total</code>: 总测试数</li><li><code>passed</code>: 通过测试数</li><li><code>failed</code>: 失败测试数</li><li><code>duration</code>: 测试持续时间（秒）</li></ul><hr><h2 id="性能基准测试" tabindex="-1">性能基准测试 <a class="header-anchor" href="#性能基准测试" aria-label="Permalink to &quot;性能基准测试&quot;">​</a></h2><h3 id="测试场景" tabindex="-1">测试场景 <a class="header-anchor" href="#测试场景" aria-label="Permalink to &quot;测试场景&quot;">​</a></h3><h4 id="pr-快速测试-ci-pr-yml" tabindex="-1">PR 快速测试（ci-pr.yml） <a class="header-anchor" href="#pr-快速测试-ci-pr-yml" aria-label="Permalink to &quot;PR 快速测试（ci-pr.yml）&quot;">​</a></h4><ul><li><strong>目的</strong>: 快速验证 PR 是否引入性能回归</li><li><strong>测试时长</strong>: 5秒/测试</li><li><strong>测试次数</strong>: 1次</li><li><strong>包含场景</strong>: <ol><li>低并发（2线程，10连接）</li><li>中等并发（4线程，50连接）</li><li>高并发（8线程，200连接）</li></ol></li></ul><h4 id="push-完整测试-ci-push-yml" tabindex="-1">Push 完整测试（ci-push.yml） <a class="header-anchor" href="#push-完整测试-ci-push-yml" aria-label="Permalink to &quot;Push 完整测试（ci-push.yml）&quot;">​</a></h4><ul><li><strong>目的</strong>: 验证代码变更后的性能</li><li><strong>测试时长</strong>: 10秒/测试</li><li><strong>测试次数</strong>: 1次</li><li><strong>包含场景</strong>: <ol><li>低并发（2线程，10连接）</li><li>中等并发（4线程，50连接）</li><li>高并发（8线程，200连接）</li><li>极限并发（16线程，500连接）</li><li>首页（小响应）</li><li>API 路由（中等响应）</li><li>静态文件（大响应）</li><li>WebSocket 连接管理</li></ol></li></ul><h4 id="nightly-完整测试-ci-nightly-yml" tabindex="-1">Nightly 完整测试（ci-nightly.yml） <a class="header-anchor" href="#nightly-完整测试-ci-nightly-yml" aria-label="Permalink to &quot;Nightly 完整测试（ci-nightly.yml）&quot;">​</a></h4><ul><li><strong>目的</strong>: 深度性能测试和趋势分析</li><li><strong>测试时长</strong>: 30秒/测试</li><li><strong>测试次数</strong>: 3次（取平均值）</li><li><strong>包含场景</strong>: 同 Push 完整测试</li></ul><h3 id="性能指标" tabindex="-1">性能指标 <a class="header-anchor" href="#性能指标" aria-label="Permalink to &quot;性能指标&quot;">​</a></h3><ul><li><strong>RPS (Requests Per Second)</strong>: 每秒请求数</li><li><strong>Latency</strong>: 平均延迟</li><li><strong>Transfer/sec</strong>: 每秒传输量</li><li><strong>Requests/sec</strong>: 每秒请求数（总计）</li></ul><h3 id="性能回归检测" tabindex="-1">性能回归检测 <a class="header-anchor" href="#性能回归检测" aria-label="Permalink to &quot;性能回归检测&quot;">​</a></h3><ul><li><strong>基线</strong>: 从 <code>docs/performance/baseline.json</code> 读取</li><li><strong>阈值</strong>: 性能下降超过 5% 视为回归</li><li><strong>动作</strong>: 检测到回归时，阻止 workflow 并创建 Issue</li></ul><hr><h2 id="产物保留策略" tabindex="-1">产物保留策略 <a class="header-anchor" href="#产物保留策略" aria-label="Permalink to &quot;产物保留策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产物类型</th><th>保留时间</th><th>说明</th></tr></thead><tbody><tr><td>PR 构建产物</td><td>7天</td><td>快速验证，短期保留</td></tr><tr><td>Push 构建产物</td><td>7天</td><td>代码验证，短期保留</td></tr><tr><td>Nightly 测试结果</td><td>30天</td><td>深度测试，中期保留</td></tr><tr><td>Release 构建产物</td><td>30天</td><td>发布版本，中期保留</td></tr><tr><td>性能测试结果</td><td>30天</td><td>性能分析，中期保留</td></tr><tr><td>代码质量分析结果</td><td>7-30天</td><td>质量跟踪，根据重要性保留</td></tr></tbody></table><hr><h2 id="缓存策略" tabindex="-1">缓存策略 <a class="header-anchor" href="#缓存策略" aria-label="Permalink to &quot;缓存策略&quot;">​</a></h2><h3 id="依赖缓存" tabindex="-1">依赖缓存 <a class="header-anchor" href="#依赖缓存" aria-label="Permalink to &quot;依赖缓存&quot;">​</a></h3><p><strong>使用</strong>: cache-deps action</p><p><strong>缓存路径</strong>:</p><ul><li><code>deps/libuv/build</code></li><li><code>deps/mbedtls/build</code></li><li><code>deps/xxhash/libxxhash.a</code></li><li><code>deps/cllhttp/build</code></li><li><code>deps/mimalloc/build</code></li><li><code>deps/googletest/build</code></li><li><code>deps/cjson/build</code></li></ul><p><strong>缓存键</strong>: <code>deps-{RUNNER_OS}-{BUILD_TYPE}-{HASH}</code></p><p><strong>恢复键</strong>: <code>deps-{RUNNER_OS}-{BUILD_TYPE}-</code></p><hr><h2 id="通知机制" tabindex="-1">通知机制 <a class="header-anchor" href="#通知机制" aria-label="Permalink to &quot;通知机制&quot;">​</a></h2><h3 id="pr-评论" tabindex="-1">PR 评论 <a class="header-anchor" href="#pr-评论" aria-label="Permalink to &quot;PR 评论&quot;">​</a></h3><p><strong>触发</strong>: ci-pr.yml 完成</p><p><strong>内容</strong>:</p><ul><li>构建状态</li><li>测试结果</li><li>代码质量</li><li>性能回归检测</li><li>依赖漏洞</li></ul><h3 id="issue-创建" tabindex="-1">Issue 创建 <a class="header-anchor" href="#issue-创建" aria-label="Permalink to &quot;Issue 创建&quot;">​</a></h3><p><strong>触发</strong>: 严重失败或安全问题</p><p><strong>内容</strong>:</p><ul><li>失败详情</li><li>错误日志</li><li>修复建议</li></ul><h3 id="github-step-summary" tabindex="-1">GitHub Step Summary <a class="header-anchor" href="#github-step-summary" aria-label="Permalink to &quot;GitHub Step Summary&quot;">​</a></h3><p><strong>触发</strong>: 所有 workflow 完成</p><p><strong>内容</strong>:</p><ul><li>CI/CD 摘要</li><li>测试结果</li><li>性能指标</li><li>代码质量</li></ul><hr><h2 id="安全扫描" tabindex="-1">安全扫描 <a class="header-anchor" href="#安全扫描" aria-label="Permalink to &quot;安全扫描&quot;">​</a></h2><h3 id="codeql" tabindex="-1">CodeQL <a class="header-anchor" href="#codeql" aria-label="Permalink to &quot;CodeQL&quot;">​</a></h3><p><strong>运行</strong>: ci-push.yml, ci-nightly.yml</p><p><strong>语言</strong>: C++</p><p><strong>查询</strong>: security-extended, security-and-quality</p><h3 id="cppcheck" tabindex="-1">cppcheck <a class="header-anchor" href="#cppcheck" aria-label="Permalink to &quot;cppcheck&quot;">​</a></h3><p><strong>运行</strong>: 所有 workflow</p><p><strong>启用</strong>: warning, performance, portability</p><p><strong>抑制</strong>:</p><ul><li>missingIncludeSystem</li><li>unusedFunction</li><li>constParameter</li><li>unusedStructMember</li></ul><h3 id="依赖扫描" tabindex="-1">依赖扫描 <a class="header-anchor" href="#依赖扫描" aria-label="Permalink to &quot;依赖扫描&quot;">​</a></h3><p><strong>运行</strong>: dependency-scan job</p><p><strong>检查</strong>: .gitmodules 中的依赖</p><hr><h2 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h2><h3 id="构建优化" tabindex="-1">构建优化 <a class="header-anchor" href="#构建优化" aria-label="Permalink to &quot;构建优化&quot;">​</a></h3><ul><li>并行编译：<code>-j$(nproc)</code></li><li>零警告原则：编译警告导致失败</li><li>增量构建：依赖缓存</li></ul><h3 id="测试优化" tabindex="-1">测试优化 <a class="header-anchor" href="#测试优化" aria-label="Permalink to &quot;测试优化&quot;">​</a></h3><ul><li>并行测试：根据测试类型调整</li><li>测试超时：根据测试类型设置</li><li>快速测试：排除慢速、压力、内存测试</li></ul><h3 id="缓存优化" tabindex="-1">缓存优化 <a class="header-anchor" href="#缓存优化" aria-label="Permalink to &quot;缓存优化&quot;">​</a></h3><ul><li>依赖缓存：缓存编译依赖</li><li>智能恢复：基于文件哈希恢复缓存</li></ul><hr><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><h4 id="_1-构建失败" tabindex="-1">1. 构建失败 <a class="header-anchor" href="#_1-构建失败" aria-label="Permalink to &quot;1. 构建失败&quot;">​</a></h4><p><strong>检查</strong>:</p><ul><li>编译警告</li><li>依赖安装</li><li>子模块更新</li></ul><p><strong>解决</strong>:</p><ul><li>修复编译警告</li><li>检查 CMakeLists.txt</li><li>更新子模块</li></ul><h4 id="_2-测试失败" tabindex="-1">2. 测试失败 <a class="header-anchor" href="#_2-测试失败" aria-label="Permalink to &quot;2. 测试失败&quot;">​</a></h4><p><strong>检查</strong>:</p><ul><li>测试日志</li><li>构建产物</li><li>测试超时</li></ul><p><strong>解决</strong>:</p><ul><li>查看测试日志</li><li>检查测试代码</li><li>调整测试超时</li></ul><h4 id="_3-性能回归" tabindex="-1">3. 性能回归 <a class="header-anchor" href="#_3-性能回归" aria-label="Permalink to &quot;3. 性能回归&quot;">​</a></h4><p><strong>检查</strong>:</p><ul><li>性能基线</li><li>测试场景</li><li>性能报告</li></ul><p><strong>解决</strong>:</p><ul><li>对比基线</li><li>分析性能瓶颈</li><li>优化代码</li></ul><h4 id="_4-安全扫描失败" tabindex="-1">4. 安全扫描失败 <a class="header-anchor" href="#_4-安全扫描失败" aria-label="Permalink to &quot;4. 安全扫描失败&quot;">​</a></h4><p><strong>检查</strong>:</p><ul><li>cppcheck 结果</li><li>CodeQL 结果</li><li>依赖漏洞</li></ul><p><strong>解决</strong>:</p><ul><li>修复安全问题</li><li>更新依赖</li><li>添加抑制规则</li></ul><hr><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><h3 id="_1-提交前检查" tabindex="-1">1. 提交前检查 <a class="header-anchor" href="#_1-提交前检查" aria-label="Permalink to &quot;1. 提交前检查&quot;">​</a></h3><ul><li>运行本地测试</li><li>检查编译警告</li><li>运行性能测试</li><li>更新文档</li></ul><h3 id="_2-pr-指南" tabindex="-1">2. PR 指南 <a class="header-anchor" href="#_2-pr-指南" aria-label="Permalink to &quot;2. PR 指南&quot;">​</a></h3><ul><li>确保所有测试通过</li><li>无性能回归</li><li>无安全问题</li><li>更新相关文档</li></ul><h3 id="_3-发布流程" tabindex="-1">3. 发布流程 <a class="header-anchor" href="#_3-发布流程" aria-label="Permalink to &quot;3. 发布流程&quot;">​</a></h3><ul><li>更新版本号</li><li>运行完整测试</li><li>创建 Release Notes</li><li>更新文档</li></ul><h3 id="_4-性能优化" tabindex="-1">4. 性能优化 <a class="header-anchor" href="#_4-性能优化" aria-label="Permalink to &quot;4. 性能优化&quot;">​</a></h3><ul><li>使用性能分析工具</li><li>优化热点代码</li><li>更新性能基线</li><li>监控性能趋势</li></ul><hr><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/actions" target="_blank" rel="noreferrer">GitHub Actions 文档</a></li><li><a href="https://cmake.org/documentation/" target="_blank" rel="noreferrer">CMake 文档</a></li><li><a href="https://cmake.org/cmake/help/latest/manual/ctest.1.html" target="_blank" rel="noreferrer">ctest 文档</a></li><li><a href="https://codeql.github.com/docs/" target="_blank" rel="noreferrer">CodeQL 文档</a></li><li><a href="https://cppcheck.sourceforge.io/manual.html" target="_blank" rel="noreferrer">cppcheck 文档</a></li><li><a href="https://github.com/wg/wrk" target="_blank" rel="noreferrer">wrk 文档</a></li></ul><hr><h2 id="变更历史" tabindex="-1">变更历史 <a class="header-anchor" href="#变更历史" aria-label="Permalink to &quot;变更历史&quot;">​</a></h2><h3 id="v2-2-0-2026-01-29" tabindex="-1">v2.2.0 (2026-01-29) <a class="header-anchor" href="#v2-2-0-2026-01-29" aria-label="Permalink to &quot;v2.2.0 (2026-01-29)&quot;">​</a></h3><p><strong>重构</strong>:</p><ul><li>删除非 Linux 平台支持（macOS、Windows）</li><li>删除冗余工作流（ci.yml、deploy.yml）</li><li>充分复用可重用 Actions（run-tests）</li><li>统一缓存策略</li><li>优化通知服务触发条件</li></ul><p><strong>优化</strong>:</p><ul><li>PR 验证时间减少 25%</li><li>Push 验证时间减少 22%</li><li>Nightly 测试时间减少 17%</li><li>CI 运行次数减少 20%</li><li>产物存储减少 50%</li></ul><p><strong>新增</strong>:</p><ul><li>性能回归检测（ci-pr.yml）</li><li>统一测试输出格式</li><li>改进的通知机制</li></ul><hr><h2 id="贡献指南" tabindex="-1">贡献指南 <a class="header-anchor" href="#贡献指南" aria-label="Permalink to &quot;贡献指南&quot;">​</a></h2><p>如需修改 CI/CD 配置：</p><ol><li>理解现有工作流和依赖关系</li><li>测试修改的工作流</li><li>更新本文档</li><li>提交 PR 并说明变更</li></ol><hr><p><strong>最后更新</strong>: 2026-01-29 <strong>维护者</strong>: UVHTTP 开发团队 <strong>许可证</strong>: MIT License</p>',237)])])}const b=t(r,[["render",o]]);export{g as __pageData,b as default};
